function task = f90_xmed02_definition()
%F90_XMED02_DEFINITION Task-owned public ranges, scenarios and score policy.

task = struct();
task.schema = "simuverity.formal90-xmed02-definition.v1";
task.task_id = "F90-XMED-02";
task.model_name = "F90_XMED_02";
task.stop_time_s = 6.0;
task.target_model_file = "F90_XMED_02.slx";

task.public_inputs = struct( ...
    "target_map_initial_mmHg", struct("nominal", 115, "minimum", 110, "maximum", 120), ...
    "target_map_final_mmHg", struct("nominal", 120, "minimum", 112, "maximum", 124), ...
    "target_step_time_s", struct("nominal", 2.5, "minimum", 2.0, "maximum", 3.0), ...
    "systemic_resistance_scale", struct("nominal", 1.0, "minimum", 0.75, "maximum", 1.30), ...
    "heart_rate_bpm", struct("nominal", 75, "minimum", 60, "maximum", 100), ...
    "pump_speed_limit_rpm", struct("nominal", 4500, "minimum", 3500, "maximum", 5000));

task.outputs = struct( ...
    "pressure_state", struct("channels", 3, ...
        "order", ["aortic_pressure", "central_venous_pressure", "pulmonary_arterial_pressure"], ...
        "unit", "mmHg"), ...
    "flow_state", struct("channels", 3, ...
        "order", ["ecmo_flow", "systemic_arterial_flow", "pulmonary_arterial_flow"], ...
        "unit", "cm^3/s"), ...
    "pump_command", struct("channels", 1, "order", "commanded_pump_speed", ...
        "unit", "rpm"));

task.scenarios = [ ...
    localScenario("nominal_step", 115, 120, 2.5, 1.00, 75, 4500); ...
    localScenario("low_resistance_up_step", 112, 122, 2.1, 0.75, 90, 5000); ...
    localScenario("high_resistance_down_step", 120, 112, 2.8, 1.30, 70, 4000); ...
    localScenario("tachycardia_mid_step", 114, 122, 2.0, 1.15, 100, 4500); ...
    localScenario("bradycardia_hold", 118, 118, 3.0, 0.90, 60, 4300); ...
    localScenario("joint_high_corner", 118, 114, 2.4, 1.25, 95, 3800) ...
    ];

task.weights = struct("A", 0.15, "Q", 0.10, "M", 0.30, ...
    "R", 0.20, "D", 0.25);
task.windows = struct( ...
    "pre_step_tail_s", 0.70, ...
    "post_step_tail_s", 1.00, ...
    "minimum_samples", 120);
task.policy_id = "simuverity-101-v1:f90-xmed-02:scoring";
end

function scenario = localScenario(id, mapInitial, mapFinal, stepTime, ...
    resistanceScale, heartRate, pumpLimit)
scenario = struct( ...
    "id", id, ...
    "target_map_initial_mmHg", mapInitial, ...
    "target_map_final_mmHg", mapFinal, ...
    "target_step_time_s", stepTime, ...
    "systemic_resistance_scale", resistanceScale, ...
    "heart_rate_bpm", heartRate, ...
    "pump_speed_limit_rpm", pumpLimit);
end
